// Shared shape of the hackathon mock dataset (mock/kits.json).
// Generated by scripts/gen-mock.ts (Claude), consumed by scripts/seed-mock.ts, worker/steps/mock.ts and src/lib/demoKit.ts.
// Money in cents. Timecodes in seconds relative to the (fictional) source video.

export type MockMarket = "GB" | "DE" | "AU" | "CA";

export interface MockKit {
  slug: string;                       // "speckled-stoneware-mug" — stable id, also the image folder name
  category: string;                   // "ceramic mug"
  product_title: string;              // "Hand-thrown Speckled Stoneware Mug" (result-screen H1)
  image_queries: string[];            // 3–5 search phrases for CC photo lookup, most specific first
  seller: { name: string; city: string; state: string; craft: string };
  source: { video_name: string; duration_sec: number; fps: number; photos: number };
  attributes: {
    materials: string[]; colors: string[]; dimensions: Record<string, number | string>;
    care: string[]; production_hours: number; made_to_order: boolean; lead_time_days: [number, number];
  };
  scenes: { label: string; start_sec: number; end_sec: number; what_happens: string }[];
  frames: { role: "hero" | "in_hand" | "detail" | "process" | "scale"; timecode_sec: number | null; score: number; reason: string }[];
  listing: {
    title: string;                    // ≤140 chars
    tags: string[];                   // exactly 13, lowercase, ≤20 chars each
    description: string;              // 180–260 words, paragraphs separated by blank lines
    price_cents: number; price_low_cents: number; price_high_cents: number; comparables_read: number;
    cost_basis_cents: number; price_reasoning: string;
  };
  videos: {
    kind: "listing" | "short"; platform: "etsy" | "tiktok" | "reels" | "shorts";
    hook_text: string | null; hook_rationale: string | null; duration_sec: number;
    cuts: { in: number; out: number; caption: string | null }[];
  }[];
  localizations: { market: MockMarket; locale: string; currency: string; price_cents: number; title: string; tags: string[]; description: string }[];
  social: { pin_title: string; pin_caption: string; carousel_caption: string };
  what_claude_did: { step: string; summary: string }[];   // 10 steps in pipeline order, numbers inside
  build_seconds: number;              // 150–330
  minutes_saved_est: number;          // 170–200
}
